1	const SENSITIVE_TOKENS = new Set([
2	  'authorization', 'auth', 'credential', 'credentials', 'cookie', 'token',
3	  'password', 'secret', 'apikey', 'session', 'email', 'phone', 'mobile',
4	  'telephone', 'national', 'idcard', 'passport', 'ssn', 'creditcard',
5	  'cardnumber', 'bankaccount', 'accountnumber',
6	]);
7	
8	const SAFE_STATUS_VALUES = new Set([
9	  'active', 'absent', 'closed', 'expired', 'failed', 'invalid', 'none', 'open',
10	  'present', 'sent', 'success', 'unset', 'valid', 'verified',
11	]);
12	const SAFE_TYPE_VALUES = new Set([
13	  'access', 'basic', 'bearer', 'business', 'digest', 'home', 'oauth', 'other',
14	  'personal', 'refresh', 'work',
15	]);
16	const INLINE_SENSITIVE_VALUES = [
17	  /\bBearer\s+[A-Za-z0-9._~+/=-]{8,}/gi,
18	  /\b[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g,
19	  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
20	  /(?<!\d)(?:\+?86[-\s]?)?1[3-9]\d{9}(?!\d)/g,
21	];
22	
23	function normalizedTokens(key: string): string[] {
24	  return key.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase().match(/[a-z0-9]+/g) ?? [];
25	}
26	
27	function isSensitiveField(key: string, value: unknown): boolean {
28	  const tokens = normalizedTokens(key);
29	  const tokenSet = new Set(tokens);
30	  const joined = `_${tokens.join('_')}_`;
31	  const sensitive = tokens.some((token) => SENSITIVE_TOKENS.has(token)) ||
32	    ['api_key', 'access_key', 'private_key', 'secret_key', 'credit_card',
33	      'card_number', 'bank_account', 'account_number', 'national_id', 'id_card']
34	      .some((field) => joined.includes(`_${field}_`));
35	  if (!sensitive) return false;
36	  if (value == null || value === '') return false;
37	  const metadata = ['status', 'verified', 'valid', 'enabled', 'configured', 'count', 'length', 'type']
38	    .some((token) => tokenSet.has(token));
39	  if (!metadata) return true;
40	  if (typeof value === 'boolean') return false;
41	  if ((tokenSet.has('count') || tokenSet.has('length')) &&
42	      typeof value === 'number' && Number.isInteger(value) && value >= 0) return false;
43	  if (typeof value === 'string' && tokenSet.has('status') && SAFE_STATUS_VALUES.has(value.toLowerCase())) return false;
44	  if (typeof value === 'string' && tokenSet.has('type') && SAFE_TYPE_VALUES.has(value.toLowerCase())) return false;
45	  return true;
46	}
47	
48	function redactString(value: string): string {
49	  const pemSafe = value.replace(
50	    /-----BEGIN ([A-Z0-9 ]*PRIVATE KEY)-----[\s\S]*?(?:-----END \1-----|$)/g,
51	    '[REDACTED]',
52	  );
53	  const assignmentsSafe = pemSafe.replace(
54	    /(^|[?&;\s])([^=&#;\s]+)=([^&#;\s]*)/g,
55	    (match, prefix: string, key: string, secret: string) =>
56	      isSensitiveField(key, secret) ? `${prefix}${key}=[REDACTED]` : match,
57	  );
58	  return INLINE_SENSITIVE_VALUES.reduce(
59	    (result, pattern) => result.replace(pattern, '[REDACTED]'),
60	    assignmentsSafe,
61	  );
62	}
63	
64	export function redact(value: unknown): unknown {
65	  if (Array.isArray(value)) return value.map(redact);
66	  if (value && typeof value === 'object') {
67	    return Object.fromEntries(
68	      Object.entries(value).map(([key, item]) => [
69	        key,
70	        isSensitiveField(key, item) ? '[REDACTED]' : redact(item),
71	      ]),
72	    );
73	  }
74	  if (typeof value === 'string') return redactString(value);
75	  return value;
76	}
