3	export type ApiRequest = {
4	  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
5	  url: string;
6	  headers?: HeadersInit;
7	  body?: BodyInit;
8	  timeoutMs: number;
9	};
10	
11	export type ApiResponse = {
12	  method: ApiRequest['method'];
13	  url: string;
14	  status: number;
15	  headers: Headers;
16	  text: string;
17	  body: unknown;
18	  durationMs: number;
19	  correlationId: string | null;
20	  evidence: {
21	    redacted: true;
22	    request: { method: string; url: string; headers: Record<string, string>; body: unknown };
23	    response: {
24	      status: number;
25	      body: unknown;
26	      durationMs: number;
27	      correlationId: string | null;
28	    };
29	  };
30	};
31	
32	export async function request(input: ApiRequest): Promise<ApiResponse> {
33	  if (!Number.isFinite(input.timeoutMs) || input.timeoutMs <= 0) {
34	    throw new RangeError('timeoutMs must be an explicit positive finite number');
35	  }
36	
37	  const requestHeaders = new Headers(input.headers);
38	  let requestBody: unknown = input.body ?? null;
39	  if (typeof input.body === 'string') {
40	    try {
41	      requestBody = JSON.parse(input.body) as unknown;
42	    } catch {
43	      requestBody = input.body;
44	    }
45	  }
46	  const started = performance.now();
47	  const response = await fetch(input.url, {
48	    method: input.method,
49	    headers: requestHeaders,
50	    body: input.body,
51	    signal: AbortSignal.timeout(input.timeoutMs),
52	  });
53	  const text = await response.text();
54	  let body: unknown = text;
55	  try {
56	    body = JSON.parse(text) as unknown;
57	  } catch {
58	    // Keep non-JSON responses as text for both assertions and evidence.
59	  }
60	  const durationMs = Math.round(performance.now() - started);
61	  const correlationId = response.headers.get('x-request-id') ??
62	    response.headers.get('x-correlation-id');
63	  const evidence = redact({
64	    redacted: true,
65	    request: {
66	      method: input.method,
67	      url: input.url,
68	      headers: Object.fromEntries(requestHeaders.entries()),
69	      body: requestBody,
70	    },
71	    response: { status: response.status, body, durationMs, correlationId },
72	  }) as ApiResponse['evidence'];
73	  return {
74	    method: input.method,
75	    url: input.url,
76	    status: response.status,
77	    headers: response.headers,
78	    text,
79	    body,
80	    durationMs,
81	    correlationId,
82	    evidence,
83	  };
84	}
